const tabId = 725790001;
const data = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll(".usa-card, .card, .program-card, [class*='card'], .grid-col, li, tr")).map(el => {
    const heading = el.querySelector("h2, h3, h4, .title, strong");
    const link = el.querySelector("a");
    const desc = el.querySelector("p, .description");
    if (heading && link) {
      return {
        heading: heading.textContent?.trim(),
        text: link.textContent?.trim(),
        href: link.href,
        desc: desc?.textContent?.trim()
      };
    }
    return null;
  }).filter(Boolean);
  return cards;
});

console.log("Found structured cards:", data.length);
console.log(JSON.stringify(data.slice(0, 30), null, 2));

