  { key: "hsls_data", url: "https://nces.ed.gov/surveys/hsls09/hsls09_data.asp" },
  // Finalist 2: ECLS-K:2011
  { key: "ecls_overview", url: "https://nces.ed.gov/ecls/kindergarten2011.asp" },
  { key: "ecls_data", url: "https://nces.ed.gov/ecls/dataproducts.asp" },
  // Finalist 3: BPS
  { key: "bps_overview", url: "https://nces.ed.gov/surveys/bps/" },
  { key: "bps_data", url: "https://nces.ed.gov/surveys/bps/availabledata.asp" },
