  const headings = Array.from(document.querySelectorAll("h2, h3"));
  const h = headings.find(el => el.textContent?.trim() === "Postsecondary");
  if (!h) return "Not found";
  let cur = h.nextElementSibling;
  let items = [];
  while (cur && cur.tagName !== "H2") {
    items.push({ tag: cur.tagName, text: cur.textContent?.trim().slice(0, 100), links: Array.from(cur.querySelectorAll("a")).map(a => ({ text: a.textContent.trim(), href: a.href })) });
    cur = cur.nextElementSibling;
  }
  return items;
});

