// Let's create the tabs for the finalists
const targetPages = [
  // Finalist 1: HSLS:09
  { key: "hsls_overview", url: "https://nces.ed.gov/surveys/hsls09/" },
  { key: "hsls_data", url: "https://nces.ed.gov/surveys/hsls09/hsls09_data.asp" },
  // Finalist 2: ECLS-K:2011
  { key: "ecls_overview", url: "https://nces.ed.gov/ecls/kindergarten2011.asp" },
  { key: "ecls_data", url: "https://nces.ed.gov/ecls/dataproducts.asp" },
  // Finalist 3: BPS
  { key: "bps_overview", url: "https://nces.ed.gov/surveys/bps/" },
  { key: "bps_data", url: "https://nces.ed.gov/surveys/bps/availabledata.asp" },
  // Finalist 4: IPEDS
  { key: "ipeds_overview", url: "https://nces.ed.gov/ipeds/" },
  { key: "ipeds_data", url: "https://nces.ed.gov/ipeds/use-the-data" },
  // Finalist 5: NAEP
  { key: "naep_overview", url: "https://nces.ed.gov/nationsreportcard/" },
  { key: "naep_data", url: "https://nces.ed.gov/nationsreportcard/researchcenter/datatools.aspx" }
];

// Reuse tab 725790001 for the first one, then create the rest
const results = [];

// Navigate existing tab 725790001
await tool.navigate({ tabId: 725790001, url: targetPages[0].url });
await tool.wait_for({ tabId: 725790001, condition: "load_state", value: "load", timeout_ms: 15000 });
results.push({
  key: targetPages[0].key,
  tabId: 725790001,
  url: targetPages[0].url
});

// Create tabs for the remaining 9 pages
for (let i = 1; i < targetPages.length; i++) {
  const page = targetPages[i];
  const newTab = await tool.tabs_create({ url: page.url });
  const tId = newTab.details.tabId;
  await tool.wait_for({ tabId: tId, condition: "load_state", value: "load", timeout_ms: 15000 });
  results.push({
    key: page.key,
    tabId: tId,
    url: page.url
  });
}

console.log("All finalist tabs created and loaded:", results.length);

